(limit, MOD) = (int(2 * 10 ** 6 + 10), int(10 ** 9) + 7)
(factorial, invFactorial) = ([0] * limit, [0] * limit)

def calFactorial():
	limit = int(2 * 10 ** 6 + 10)
	(factorial[0], factorial[1], invFactorial[0], invFactorial[1]) = (1, 1, 1, 1)
	for i in range(2, limit):
		factorial[i] = factorial[i - 1] * i % MOD
	for i in range(2, limit):
		invFactorial[i] = (MOD - MOD // i * invFactorial[MOD % i]) % MOD
	for i in range(1, limit):
		invFactorial[i] = invFactorial[i - 1] * invFactorial[i] % MOD

def nCr(N, R):
	if R > N:
		return 0
	ans = factorial[N] * invFactorial[R] % MOD * invFactorial[N - R]
	ans %= MOD
	return ans

def solve(N, K):
	ans = 2 * nCr(N + K + 1, K + 2) - N
	ans = (ans % MOD + MOD) % MOD
	print(ans)
calFactorial()
T = int(input())
for _ in range(T):
	(N, K) = map(int, input().split())
	solve(N, K)
